/**
 * Domain ke liye activity + skills get karo (index ke hisaab se)
 */
export const getDomainLogbookEntry = (domainName, index = 0) => {
  const key = String(domainName || "").trim();
  const entries = DOMAIN_LOGBOOK_DATA[key];

  if (!entries || entries.length === 0) {
    return {
      activity: `Day ${index + 1}: Completed assigned learning tasks and internship activities.`,
      skills: "Technical learning, communication, and professional skills.",
    };
  }

  return entries[index % entries.length];
};

export default DOMAIN_LOGBOOK_DATA;